<?php
// Portly dashboard (http://localhost). Generated by Portly - reachable only from this computer.
declare(strict_types=1);

if (isset($_GET['phpinfo'])) {
    phpinfo();
    exit;
}

$raw = @file_get_contents(__DIR__ . '/data.json');
$d = is_string($raw) ? json_decode($raw, true) : null;
if (!is_array($d)) {
    $d = ['sites' => [], 'tools' => [], 't' => [], 'version' => '', 'edition' => '', 'docRoot' => ''];
}
$t = $d['t'] ?? [];
function e($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function tr(array $t, string $k, string $def): string { return isset($t[$k]) && $t[$k] !== '' ? (string)$t[$k] : $def; }
$lang = preg_match('/^[a-z]{2}(-[A-Z]{2})?$/', (string)($t['lang'] ?? 'en')) ? $t['lang'] : 'en';
?>
<!doctype html>
<html lang="<?= e($lang) ?>">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Portly</title>
<style>
:root{--bg:#f5f7fb;--card:#fff;--text:#1c2433;--muted:#667085;--line:#e4e7ec;--accent:#2563eb;--bad:#b42318}
@media (prefers-color-scheme:dark){:root{--bg:#0f1420;--card:#171e2d;--text:#e6e9ef;--muted:#98a2b3;--line:#283044;--accent:#60a5fa;--bad:#f97066}}
*{box-sizing:border-box}
body{margin:0;font:15px/1.5 "Segoe UI",system-ui,sans-serif;background:var(--bg);color:var(--text)}
header{display:flex;align-items:center;gap:14px;padding:28px 32px 8px;max-width:1100px;margin:0 auto}
.logo{width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,#2563eb,#0ea5e9);display:grid;place-items:center;color:#fff;font-weight:700;font-size:24px}
h1{margin:0;font-size:24px}
.sub{color:var(--muted);font-size:13px}
main{max-width:1100px;margin:0 auto;padding:8px 32px 40px}
h2{font-size:15px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);margin:28px 0 12px}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:12px}
a.card,.card{display:block;background:var(--card);border:1px solid var(--line);border-radius:12px;padding:14px 16px;text-decoration:none;color:var(--text);transition:border-color .15s,transform .15s}
a.card:hover{border-color:var(--accent);transform:translateY(-1px)}
.name{font-weight:600;word-break:break-all}
.meta{color:var(--muted);font-size:12.5px;word-break:break-all}
.bad .meta{color:var(--bad)}
.empty{color:var(--muted)}
footer{max-width:1100px;margin:0 auto;padding:0 32px 32px;color:var(--muted);font-size:12.5px}
footer a{color:var(--accent)}
</style>
</head>
<body>
<header>
  <div class="logo">P</div>
  <div>
    <h1><?= e(tr($t, 'title', 'Portly')) ?></h1>
    <div class="sub">Portly <?= e($d['version']) ?> · <?= e($d['edition']) ?> · PHP <?= e(PHP_VERSION) ?></div>
  </div>
</header>
<main>
  <h2><?= e(tr($t, 'sites', 'Sites')) ?></h2>
  <?php if (empty($d['sites'])): ?>
    <p class="empty"><?= e(tr($t, 'empty', 'No projects yet.')) ?></p>
  <?php else: ?>
  <div class="grid">
    <?php foreach ($d['sites'] as $s): ?>
      <?php if (!empty($s['url'])): ?>
        <a class="card" href="<?= e($s['url']) ?>">
          <div class="name"><?= e($s['name']) ?></div>
          <div class="meta"><?= e($s['url']) ?> · PHP <?= e($s['php']) ?></div>
        </a>
      <?php else: ?>
        <div class="card bad">
          <div class="name"><?= e($s['name']) ?></div>
          <div class="meta"><?= e($s['problem']) ?></div>
        </div>
      <?php endif; ?>
    <?php endforeach; ?>
  </div>
  <?php endif; ?>

  <h2><?= e(tr($t, 'tools', 'Tools')) ?></h2>
  <div class="grid">
    <?php foreach (($d['tools'] ?? []) as $tool): ?>
      <a class="card" href="<?= e($tool['url']) ?>"><div class="name"><?= e($tool['name']) ?></div><div class="meta"><?= e($tool['url']) ?></div></a>
    <?php endforeach; ?>
    <a class="card" href="?phpinfo=1"><div class="name">phpinfo()</div><div class="meta"><?= e(tr($t, 'phpinfo', 'PHP configuration')) ?></div></a>
  </div>
</main>
<footer>
  Portly · Erdem Software · <a href="<?= e($d['github'] ?? '#') ?>">GitHub</a> · <a href="<?= e($d['donate'] ?? '#') ?>"><?= e(tr($t, 'donate', 'Donate')) ?></a>
</footer>
</body>
</html>
